// contractSatFlickerGet answers zeros every second
// call, where Get should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type contractSatFlickerGet struct {
	upserter.Contract
	flip atomic.Int64
}

func (m *contractSatFlickerGet) Get(p0 context.Context, p1 string) (z0 upserter.Value, z1 error) {
	if m.flip.Add(1)%2 == 0 {
		return
	}
	return m.Contract.Get(p0, p1)
}

// contractSatSputterGet alternates a minted refusal
// with the real answer where Get should be steady.
type contractSatSputterGet struct {
	upserter.Contract
	flip atomic.Int64
}

func (m *contractSatSputterGet) Get(p0 context.Context, p1 string) (z0 upserter.Value, z1 error) {
	if m.flip.Add(1)%2 == 1 {
		z1 = errors.New("upsertertest: saturation sputtered a refusal")
		return
	}
	return m.Contract.Get(p0, p1)
}

// contractSatSpillGet refuses while answering what
// Get actually found — whatever the failed lookup left behind.
//
// Every refusal the wardrobe mints elsewhere arrives with the zero value
// beside it, and the value a failed read is supposed to answer is usually the
// zero. So the defect and the claim agree, and a law about what an error must
// coincide with has nothing that can disagree with it.
type contractSatSpillGet struct{ upserter.Contract }

func (m contractSatSpillGet) Get(p0 context.Context, p1 string) (upserter.Value, error) {
	out, err := m.Contract.Get(p0, p1)
	if err != nil {
		return out, err
	}
	return out, errors.New("upsertertest: saturation spilled a found value into a refusal")
}

